-- 도커 세트 237. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 단원·display_order 는 통합 시 별도로 정한다. 원본: 02_quest_set.sql, 03_quest_set237.sql. docs/specs/spec_docker_compose_practice_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 237, '도커 Compose 손으로 해 보기 실습: compose.yaml, up, ps, logs, exec, 환경 변수, 볼륨, -p, depends_on', '/tmp/stack 에 compose.yaml 을 직접 쓰고 alpine 서비스를 올려, 컨테이너 상태와 로그, 컨테이너 안 파일, 환경 변수로 결과를 확인합니다. ps --format, logs, exec, .env 변수 치환, 볼륨 데이터 유지, -p 프로젝트 이름, depends_on 까지 한 단계씩 익힙니다.', 'docker', '도커'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 237);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 237, 1, 'compose.yaml 쓰고 올리기', '`/tmp/stack` 에 `compose.yaml` 을 만들어 `alpine` 이미지로 서비스 **`web`** 하나를 정의하세요. 컨테이너가 바로 끝나지 않도록 `command` 는 `["sleep", "3600"]` 으로 하고, 백그라운드로 올리세요.', '파일의 맨 위는 `services:` 이고 그 아래에 서비스 이름, 다시 그 아래에 `image` 와 `command` 를 들여쓰기로 적어요. 올리기는 `docker compose up` 에 백그라운드 옵션을 붙입니다. 파일이 있는 디렉터리에서 실행하세요.', 'cd /tmp/stack
cat > compose.yaml <<''EOF''
services:
  web:
    image: alpine
    command: ["sleep", "3600"]
EOF
docker compose up -d
docker compose ps

# 프로젝트 이름은 기본적으로 디렉터리 이름(stack) 이다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; docker volume prune -f >/dev/null 2>&1; rm -rf /tmp/stack /tmp/*.txt; mkdir -p /tmp/stack; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( docker ps --filter label=com.docker.compose.project=stack --filter label=com.docker.compose.service=web --filter status=running -q | grep -q . )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "web 서비스가 실행 중이다", "cmd": ["sh", "-c", "docker ps --filter label=com.docker.compose.project=stack --filter label=com.docker.compose.service=web --filter status=running -q | grep -q ."]}]', '[{"title": "Docker 공식 문서: docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}, {"title": "Docker 공식 문서: docker compose ps", "url": "https://docs.docker.com/reference/cli/docker/compose/ps/"}, {"title": "Docker 공식 문서: docker compose logs", "url": "https://docs.docker.com/reference/cli/docker/compose/logs/"}, {"title": "Docker 공식 문서: docker compose exec", "url": "https://docs.docker.com/reference/cli/docker/compose/exec/"}, {"title": "Docker 공식 문서: Compose 파일 services", "url": "https://docs.docker.com/reference/compose-file/services/"}, {"title": "Docker 공식 문서: Compose 변수 치환", "url": "https://docs.docker.com/compose/how-tos/environment-variables/variable-interpolation/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 237 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 237, 2, '서비스 이름만 뽑아 저장', '`/tmp/stack` 에 서비스 두 개(`web`, `cache`)가 이미 떠 있습니다. 이 프로젝트의 **서비스 이름만** 한 줄에 하나씩 `/tmp/svc.txt` 에 저장하세요.', '`docker compose ps` 에도 `--format` 이 있어요. 서비스 이름 항목은 `{{.Service}}` 입니다. 같은 디렉터리에서 실행하세요.', 'cd /tmp/stack
docker compose ps
docker compose ps --format ''{{.Service}}'' | sort > /tmp/svc.txt
cat /tmp/svc.txt

# 컨테이너 이름(stack-web-1)이 아니라 서비스 이름(web)을 뽑는다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; docker volume prune -f >/dev/null 2>&1; rm -rf /tmp/stack /tmp/*.txt; mkdir -p /tmp/stack; docker pull -q alpine >/dev/null 2>&1; cat > /tmp/stack/compose.yaml <<''EOF''\\nservices:\\n  web:\\n    image: alpine\\n    command: [\\"sleep\\", \\"3600\\"]\\n  cache:\\n    image: alpine\\n    command: [\\"sleep\\", \\"3600\\"]\\n\\nEOF\\ncd /tmp/stack && docker compose up -d >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(sort /tmp/svc.txt)\\" = \\"$(printf ''cache\\\\nweb'')\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "서비스 이름 두 개가 들어 있다", "cmd": ["sh", "-c", "[ \\"$(sort /tmp/svc.txt)\\" = \\"$(printf ''cache\\\\nweb'')\\" ]"]}]', '[{"title": "Docker 공식 문서: docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}, {"title": "Docker 공식 문서: docker compose ps", "url": "https://docs.docker.com/reference/cli/docker/compose/ps/"}, {"title": "Docker 공식 문서: docker compose logs", "url": "https://docs.docker.com/reference/cli/docker/compose/logs/"}, {"title": "Docker 공식 문서: docker compose exec", "url": "https://docs.docker.com/reference/cli/docker/compose/exec/"}, {"title": "Docker 공식 문서: Compose 파일 services", "url": "https://docs.docker.com/reference/compose-file/services/"}, {"title": "Docker 공식 문서: Compose 변수 치환", "url": "https://docs.docker.com/compose/how-tos/environment-variables/variable-interpolation/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 237 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 237, 3, '서비스 로그를 접두사 없이 저장', '서비스 `hello` 가 떠 있고 시작할 때 한 줄을 출력했습니다. 그 로그를 서비스 이름 접두사 **없이** `/tmp/log.txt` 에 저장하세요.', '`docker compose logs 서비스이름` 으로 볼 수 있는데, 줄 앞에 `hello-1  |` 같은 접두사가 붙어요. `docker compose logs --help` 에서 접두사를 빼는 옵션을 찾아 보세요.', 'cd /tmp/stack
docker compose logs hello
docker compose logs --no-log-prefix hello > /tmp/log.txt
cat /tmp/log.txt

# --no-log-prefix 는 줄 앞의 컨테이너 이름 표시를 뺀다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; docker volume prune -f >/dev/null 2>&1; rm -rf /tmp/stack /tmp/*.txt; mkdir -p /tmp/stack; docker pull -q alpine >/dev/null 2>&1; cat > /tmp/stack/compose.yaml <<''EOF''\\nservices:\\n  hello:\\n    image: alpine\\n    command: [\\"sh\\", \\"-c\\", \\"echo boot ok; sleep 3600\\"]\\n\\nEOF\\ncd /tmp/stack && docker compose up -d >/dev/null 2>&1; sleep 2; true"]', '["sh", "-c", "( grep -qx \\"boot ok\\" /tmp/log.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "로그에 boot ok 줄이 접두사 없이 있다", "cmd": ["sh", "-c", "grep -qx \\"boot ok\\" /tmp/log.txt"]}]', '[{"title": "Docker 공식 문서: docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}, {"title": "Docker 공식 문서: docker compose ps", "url": "https://docs.docker.com/reference/cli/docker/compose/ps/"}, {"title": "Docker 공식 문서: docker compose logs", "url": "https://docs.docker.com/reference/cli/docker/compose/logs/"}, {"title": "Docker 공식 문서: docker compose exec", "url": "https://docs.docker.com/reference/cli/docker/compose/exec/"}, {"title": "Docker 공식 문서: Compose 파일 services", "url": "https://docs.docker.com/reference/compose-file/services/"}, {"title": "Docker 공식 문서: Compose 변수 치환", "url": "https://docs.docker.com/compose/how-tos/environment-variables/variable-interpolation/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 237 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 237, 4, '서비스 안에서 명령 실행', '서비스 `app` 이 떠 있습니다. 이 서비스의 컨테이너 안에서 `/tmp/mark` 파일에 `done` 을 쓰세요. (호스트가 아니라 컨테이너 안에 만들어야 합니다)', '`docker compose exec 서비스이름 명령` 은 이미 떠 있는 서비스에서 명령을 실행해요. 파일에 쓰려면 `sh -c` 로 감싸서 리다이렉션도 컨테이너 안에서 일어나게 하세요.', 'cd /tmp/stack
docker compose exec app sh -c ''echo done > /tmp/mark''
docker compose exec app cat /tmp/mark

# 서비스 이름으로 지정하면 컨테이너 이름을 몰라도 된다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; docker volume prune -f >/dev/null 2>&1; rm -rf /tmp/stack /tmp/*.txt; mkdir -p /tmp/stack; docker pull -q alpine >/dev/null 2>&1; cat > /tmp/stack/compose.yaml <<''EOF''\\nservices:\\n  app:\\n    image: alpine\\n    command: [\\"sleep\\", \\"3600\\"]\\n\\nEOF\\ncd /tmp/stack && docker compose up -d >/dev/null 2>&1; true"]', '["sh", "-c", "( cd /tmp/stack && [ \\"$(docker compose exec -T app cat /tmp/mark)\\" = done ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "app 컨테이너 안 /tmp/mark 가 done 이다", "cmd": ["sh", "-c", "cd /tmp/stack && [ \\"$(docker compose exec -T app cat /tmp/mark)\\" = done ]"]}]', '[{"title": "Docker 공식 문서: docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}, {"title": "Docker 공식 문서: docker compose ps", "url": "https://docs.docker.com/reference/cli/docker/compose/ps/"}, {"title": "Docker 공식 문서: docker compose logs", "url": "https://docs.docker.com/reference/cli/docker/compose/logs/"}, {"title": "Docker 공식 문서: docker compose exec", "url": "https://docs.docker.com/reference/cli/docker/compose/exec/"}, {"title": "Docker 공식 문서: Compose 파일 services", "url": "https://docs.docker.com/reference/compose-file/services/"}, {"title": "Docker 공식 문서: Compose 변수 치환", "url": "https://docs.docker.com/compose/how-tos/environment-variables/variable-interpolation/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 237 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 237, 5, 'command 와 이미지의 CMD', '`compose.yaml` 의 서비스에 `command: ["sleep", "3600"]` 을 적었습니다. 이 서비스가 쓰는 이미지에는 이미 `CMD` 가 있습니다. 컨테이너를 올리면 어떻게 될까요?', '이미지에 적힌 기본값과 Compose 파일에 적은 값 중 어느 쪽이 우선하는지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["이미지의 `CMD` 가 우선이라 `command` 는 무시된다", "둘이 이어 붙어서 두 명령이 함께 실행된다", "Compose 의 `command` 가 이미지의 `CMD` 를 대체해서 `sleep 3600` 이 실행된다", "`command` 와 `CMD` 가 겹치면 `docker compose up` 이 오류로 멈춘다"]', 2, 'Compose 의 `command` 는 이미지의 `CMD` 를 대체합니다. 이미지를 고치지 않고도 실행 명령만 서비스별로 바꿀 수 있는 이유예요. 이어 붙지도 않고, 겹친다고 오류가 나지도 않습니다. 참고로 `ENTRYPOINT` 는 `entrypoint` 필드로 따로 바꿉니다.', NULL, NULL, NULL, '[{"title": "Docker 공식 문서: docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}, {"title": "Docker 공식 문서: docker compose ps", "url": "https://docs.docker.com/reference/cli/docker/compose/ps/"}, {"title": "Docker 공식 문서: docker compose logs", "url": "https://docs.docker.com/reference/cli/docker/compose/logs/"}, {"title": "Docker 공식 문서: docker compose exec", "url": "https://docs.docker.com/reference/cli/docker/compose/exec/"}, {"title": "Docker 공식 문서: Compose 파일 services", "url": "https://docs.docker.com/reference/compose-file/services/"}, {"title": "Docker 공식 문서: Compose 변수 치환", "url": "https://docs.docker.com/compose/how-tos/environment-variables/variable-interpolation/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 237 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 237, 6, '서비스에 환경 변수 넣기', '`/tmp/stack/compose.yaml` 에 서비스 `app` 이 정의돼 있지만 환경 변수가 없습니다. `app` 에 환경 변수 `MODE=prod` 를 넣고 올려서, 컨테이너 안에서 `MODE` 가 `prod` 로 보이게 하세요.', '서비스 아래에 `environment:` 목록을 추가해요. 파일을 고친 뒤에는 `docker compose up -d` 를 다시 실행해야 컨테이너에 반영됩니다.', 'cd /tmp/stack
cat > compose.yaml <<''EOF''
services:
  app:
    image: alpine
    command: ["sleep", "3600"]
    environment:
      - MODE=prod
EOF
docker compose up -d
docker compose exec app printenv MODE

# 파일만 고치면 안 되고 up 으로 컨테이너를 다시 만들어야 한다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; docker volume prune -f >/dev/null 2>&1; rm -rf /tmp/stack /tmp/*.txt; mkdir -p /tmp/stack; docker pull -q alpine >/dev/null 2>&1; cat > /tmp/stack/compose.yaml <<''EOF''\\nservices:\\n  app:\\n    image: alpine\\n    command: [\\"sleep\\", \\"3600\\"]\\n\\nEOF\\ntrue"]', '["sh", "-c", "( cd /tmp/stack && [ \\"$(docker compose exec -T app printenv MODE)\\" = prod ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "app 컨테이너의 MODE 가 prod 다", "cmd": ["sh", "-c", "cd /tmp/stack && [ \\"$(docker compose exec -T app printenv MODE)\\" = prod ]"]}]', '[{"title": "Docker 공식 문서: docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}, {"title": "Docker 공식 문서: docker compose ps", "url": "https://docs.docker.com/reference/cli/docker/compose/ps/"}, {"title": "Docker 공식 문서: docker compose logs", "url": "https://docs.docker.com/reference/cli/docker/compose/logs/"}, {"title": "Docker 공식 문서: docker compose exec", "url": "https://docs.docker.com/reference/cli/docker/compose/exec/"}, {"title": "Docker 공식 문서: Compose 파일 services", "url": "https://docs.docker.com/reference/compose-file/services/"}, {"title": "Docker 공식 문서: Compose 변수 치환", "url": "https://docs.docker.com/compose/how-tos/environment-variables/variable-interpolation/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 237 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 237, 7, '.env 파일로 변수 채우기', '`/tmp/stack/compose.yaml` 의 서비스 `app` 은 환경 변수 `LEVEL` 의 값을 `${LEVEL}` 로 받게 돼 있습니다. **`compose.yaml` 은 고치지 말고**, 같은 디렉터리의 `.env` 파일로 `LEVEL` 을 `debug` 로 채워 `app` 을 올리세요.', 'Compose 는 프로젝트 디렉터리의 `.env` 파일에서 `이름=값` 을 읽어 `${이름}` 을 채워요. 확인은 `docker compose config` 로 하면 채워진 최종 설정이 보입니다.', 'cd /tmp/stack
echo ''LEVEL=debug'' > .env
docker compose config
docker compose up -d
docker compose exec app printenv LEVEL

# compose.yaml 은 그대로 두고 .env 로 값만 바꿀 수 있다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; docker volume prune -f >/dev/null 2>&1; rm -rf /tmp/stack /tmp/*.txt; mkdir -p /tmp/stack; docker pull -q alpine >/dev/null 2>&1; cat > /tmp/stack/compose.yaml <<''EOF''\\nservices:\\n  app:\\n    image: alpine\\n    command: [\\"sleep\\", \\"3600\\"]\\n    environment:\\n      - LEVEL=${LEVEL}\\n\\nEOF\\ntrue"]', '["sh", "-c", "( grep -q ''${LEVEL}'' /tmp/stack/compose.yaml ) && ( cd /tmp/stack && [ \\"$(docker compose exec -T app printenv LEVEL)\\" = debug ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "compose.yaml 은 ${LEVEL} 을 그대로 쓴다", "cmd": ["sh", "-c", "grep -q ''${LEVEL}'' /tmp/stack/compose.yaml"]}, {"label": "app 의 LEVEL 이 debug 다", "cmd": ["sh", "-c", "cd /tmp/stack && [ \\"$(docker compose exec -T app printenv LEVEL)\\" = debug ]"]}]', '[{"title": "Docker 공식 문서: docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}, {"title": "Docker 공식 문서: docker compose ps", "url": "https://docs.docker.com/reference/cli/docker/compose/ps/"}, {"title": "Docker 공식 문서: docker compose logs", "url": "https://docs.docker.com/reference/cli/docker/compose/logs/"}, {"title": "Docker 공식 문서: docker compose exec", "url": "https://docs.docker.com/reference/cli/docker/compose/exec/"}, {"title": "Docker 공식 문서: Compose 파일 services", "url": "https://docs.docker.com/reference/compose-file/services/"}, {"title": "Docker 공식 문서: Compose 변수 치환", "url": "https://docs.docker.com/compose/how-tos/environment-variables/variable-interpolation/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 237 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 237, 8, '내렸다 올려도 남는 데이터', '서비스 `db` 가 이름 있는 볼륨 `dbdata` 를 `/data` 에 연결해 떠 있습니다. `db` 의 `/data/note.txt` 에 `keep` 을 쓰세요. 그런 다음 스택을 **내렸다가 다시 올려서**(컨테이너는 새로 만들어지고) 파일이 그대로 남아 있게 하세요.', '`docker compose down` 은 컨테이너와 네트워크를 지우지만 이름 있는 볼륨은 남겨요. 다시 올린 뒤 `docker compose exec db cat /data/note.txt` 로 확인하세요.', 'cd /tmp/stack
docker compose exec db sh -c ''echo keep > /data/note.txt''
docker compose down
docker compose up -d
docker compose exec db cat /data/note.txt

# down 에 -v 를 붙이지 않으면 볼륨 데이터는 남는다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; docker volume prune -f >/dev/null 2>&1; rm -rf /tmp/stack /tmp/*.txt; mkdir -p /tmp/stack; docker pull -q alpine >/dev/null 2>&1; cat > /tmp/stack/compose.yaml <<''EOF''\\nservices:\\n  db:\\n    image: alpine\\n    command: [\\"sleep\\", \\"3600\\"]\\n    volumes:\\n      - dbdata:/data\\nvolumes:\\n  dbdata:\\nEOF\\ncd /tmp/stack && docker compose up -d >/dev/null 2>&1; (cd /tmp/stack && docker compose ps -q db) > /tmp/oldid.txt; true"]', '["sh", "-c", "( docker ps --filter label=com.docker.compose.project=stack --filter label=com.docker.compose.service=db --filter status=running -q | grep -q . ) && ( [ \\"$(cd /tmp/stack && docker compose ps -q db)\\" != \\"$(cat /tmp/oldid.txt)\\" ] ) && ( cd /tmp/stack && [ \\"$(docker compose exec -T db cat /data/note.txt)\\" = keep ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "db 가 실행 중이다", "cmd": ["sh", "-c", "docker ps --filter label=com.docker.compose.project=stack --filter label=com.docker.compose.service=db --filter status=running -q | grep -q ."]}, {"label": "컨테이너가 새로 만들어졌다", "cmd": ["sh", "-c", "[ \\"$(cd /tmp/stack && docker compose ps -q db)\\" != \\"$(cat /tmp/oldid.txt)\\" ]"]}, {"label": "note.txt 가 keep 으로 남아 있다", "cmd": ["sh", "-c", "cd /tmp/stack && [ \\"$(docker compose exec -T db cat /data/note.txt)\\" = keep ]"]}]', '[{"title": "Docker 공식 문서: docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}, {"title": "Docker 공식 문서: docker compose ps", "url": "https://docs.docker.com/reference/cli/docker/compose/ps/"}, {"title": "Docker 공식 문서: docker compose logs", "url": "https://docs.docker.com/reference/cli/docker/compose/logs/"}, {"title": "Docker 공식 문서: docker compose exec", "url": "https://docs.docker.com/reference/cli/docker/compose/exec/"}, {"title": "Docker 공식 문서: Compose 파일 services", "url": "https://docs.docker.com/reference/compose-file/services/"}, {"title": "Docker 공식 문서: Compose 변수 치환", "url": "https://docs.docker.com/compose/how-tos/environment-variables/variable-interpolation/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 237 AND order_index = 8);

