SELECT 237, 9, '서비스 로그 마지막 몇 줄만', '`web` 서비스 로그의 **마지막 5줄**만 보는 명령입니다. 빈칸을 채우세요.', '로그를 끝에서부터 몇 줄만 보는 옵션은 `--tail 줄수` 예요. 마지막에는 어느 서비스의 로그인지를 적습니다.', NULL, NULL, '[]', 'fill', '["5", "web", "-f", "ps"]', NULL, '`--tail` 뒤에는 보고 싶은 줄 수(`5`)가, 맨 끝에는 서비스 이름(`web`)이 옵니다. `-f` 는 로그를 계속 따라가는 옵션이고, `ps` 는 서브커맨드라 여기 들어갈 수 없어요.', '[0, 1]', 'docker compose logs --tail {0} {1}', NULL, '[{"title": "Docker 공식 문서: docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}, {"title": "Docker 공식 문서: docker compose ps", "url": "https://docs.docker.com/reference/cli/docker/compose/ps/"}, {"title": "Docker 공식 문서: docker compose logs", "url": "https://docs.docker.com/reference/cli/docker/compose/logs/"}, {"title": "Docker 공식 문서: docker compose exec", "url": "https://docs.docker.com/reference/cli/docker/compose/exec/"}, {"title": "Docker 공식 문서: Compose 파일 services", "url": "https://docs.docker.com/reference/compose-file/services/"}, {"title": "Docker 공식 문서: Compose 변수 치환", "url": "https://docs.docker.com/compose/how-tos/environment-variables/variable-interpolation/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 237 AND order_index = 9);

