SELECT 237, 10, '같은 파일로 프로젝트 하나 더', '`/tmp/stack/compose.yaml` 로 프로젝트 `stack` 이 이미 떠 있습니다. **같은 파일**을 그대로 써서 프로젝트 이름이 **`second`** 인 스택을 하나 더 올리세요. 기존 `stack` 은 그대로 떠 있어야 합니다.', '프로젝트 이름은 기본적으로 디렉터리 이름이지만 `docker compose -p 이름 ...` 으로 바꿀 수 있어요. 이름이 다르면 컨테이너도 따로 만들어집니다. `docker compose ls` 로 프로젝트 목록을 볼 수 있어요.', 'cd /tmp/stack
docker compose -p second up -d
docker compose ls
docker compose -p second ps

# -p 로 이름을 바꾸면 같은 파일에서 독립된 프로젝트가 하나 더 생긴다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; docker volume prune -f >/dev/null 2>&1; rm -rf /tmp/stack /tmp/*.txt; mkdir -p /tmp/stack; docker pull -q alpine >/dev/null 2>&1; cat > /tmp/stack/compose.yaml <<''EOF''\\nservices:\\n  web:\\n    image: alpine\\n    command: [\\"sleep\\", \\"3600\\"]\\n\\nEOF\\ncd /tmp/stack && docker compose up -d >/dev/null 2>&1; true"]', '["sh", "-c", "( docker ps --filter label=com.docker.compose.project=stack --filter label=com.docker.compose.service=web --filter status=running -q | grep -q . ) && ( docker ps --filter label=com.docker.compose.project=second --filter label=com.docker.compose.service=web --filter status=running -q | grep -q . )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "stack 의 web 이 그대로 떠 있다", "cmd": ["sh", "-c", "docker ps --filter label=com.docker.compose.project=stack --filter label=com.docker.compose.service=web --filter status=running -q | grep -q ."]}, {"label": "second 의 web 이 떠 있다", "cmd": ["sh", "-c", "docker ps --filter label=com.docker.compose.project=second --filter label=com.docker.compose.service=web --filter status=running -q | grep -q ."]}]', '[{"title": "Docker 공식 문서: docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}, {"title": "Docker 공식 문서: docker compose ps", "url": "https://docs.docker.com/reference/cli/docker/compose/ps/"}, {"title": "Docker 공식 문서: docker compose logs", "url": "https://docs.docker.com/reference/cli/docker/compose/logs/"}, {"title": "Docker 공식 문서: docker compose exec", "url": "https://docs.docker.com/reference/cli/docker/compose/exec/"}, {"title": "Docker 공식 문서: Compose 파일 services", "url": "https://docs.docker.com/reference/compose-file/services/"}, {"title": "Docker 공식 문서: Compose 변수 치환", "url": "https://docs.docker.com/compose/how-tos/environment-variables/variable-interpolation/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 237 AND order_index = 10);

