SELECT 237, 11, 'depends_on 으로 시작 순서 정하기', '`/tmp/stack/compose.yaml` 에 서비스 `db` 와 `app` 이 있습니다. `app` 이 `db` 에 **의존하도록** `depends_on` 을 추가하고, 두 서비스를 모두 올려 실행 중으로 만드세요.', '서비스 아래에 `depends_on:` 목록으로 먼저 떠야 할 서비스 이름을 적어요. 최종 설정에 반영됐는지는 `docker compose config` 로 볼 수 있습니다.', 'cd /tmp/stack
cat > compose.yaml <<''EOF''
services:
  db:
    image: alpine
    command: ["sleep", "3600"]
  app:
    image: alpine
    command: ["sleep", "3600"]
    depends_on:
      - db
EOF
docker compose config | grep -A2 depends_on
docker compose up -d
docker compose ps

# depends_on 이 있으면 db 가 먼저 만들어지고 시작된 뒤 app 이 시작된다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; docker volume prune -f >/dev/null 2>&1; rm -rf /tmp/stack /tmp/*.txt; mkdir -p /tmp/stack; docker pull -q alpine >/dev/null 2>&1; cat > /tmp/stack/compose.yaml <<''EOF''\\nservices:\\n  db:\\n    image: alpine\\n    command: [\\"sleep\\", \\"3600\\"]\\n  app:\\n    image: alpine\\n    command: [\\"sleep\\", \\"3600\\"]\\n\\nEOF\\ntrue"]', '["sh", "-c", "( cd /tmp/stack && docker compose config | grep -A3 depends_on | grep -q db ) && ( docker ps --filter label=com.docker.compose.project=stack --filter label=com.docker.compose.service=db --filter status=running -q | grep -q . ) && ( docker ps --filter label=com.docker.compose.project=stack --filter label=com.docker.compose.service=app --filter status=running -q | grep -q . )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "app 이 db 에 의존한다", "cmd": ["sh", "-c", "cd /tmp/stack && docker compose config | grep -A3 depends_on | grep -q db"]}, {"label": "db 가 실행 중이다", "cmd": ["sh", "-c", "docker ps --filter label=com.docker.compose.project=stack --filter label=com.docker.compose.service=db --filter status=running -q | grep -q ."]}, {"label": "app 이 실행 중이다", "cmd": ["sh", "-c", "docker ps --filter label=com.docker.compose.project=stack --filter label=com.docker.compose.service=app --filter status=running -q | grep -q ."]}]', '[{"title": "Docker 공식 문서: docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}, {"title": "Docker 공식 문서: docker compose ps", "url": "https://docs.docker.com/reference/cli/docker/compose/ps/"}, {"title": "Docker 공식 문서: docker compose logs", "url": "https://docs.docker.com/reference/cli/docker/compose/logs/"}, {"title": "Docker 공식 문서: docker compose exec", "url": "https://docs.docker.com/reference/cli/docker/compose/exec/"}, {"title": "Docker 공식 문서: Compose 파일 services", "url": "https://docs.docker.com/reference/compose-file/services/"}, {"title": "Docker 공식 문서: Compose 변수 치환", "url": "https://docs.docker.com/compose/how-tos/environment-variables/variable-interpolation/"}]'
