SELECT 237, 12, 'Compose 스택 만들고 정리하는 흐름', 'Compose 로 작은 스택을 만들고 확인한 뒤 정리하는 흐름을 **앞에서 뒤**로 놓으세요.', '파일을 쓰고 → 설정을 확인하고 → 올리고 → 상태를 보고 → 로그를 보고 → 정리하는 순서입니다.', NULL, NULL, '[]', 'order', '["`compose.yaml` 을 작성한다", "`docker compose config` 로 최종 설정이 올바른지 확인한다", "`docker compose up -d` 로 백그라운드에서 올린다", "`docker compose ps` 로 서비스 상태를 본다", "`docker compose logs` 로 서비스 로그를 확인한다", "`docker compose down` 으로 컨테이너와 네트워크를 정리한다"]', NULL, '**작성 → config → up -d → ps → logs → down** 순서입니다. `config` 로 파일이 올바른지 먼저 확인하면 잘못된 파일을 올리는 일을 막고, 올린 뒤에는 `ps` 로 상태를, `logs` 로 동작을 확인합니다. 마지막 `down` 으로 만든 것을 정리해요.', '[0, 1, 2, 3, 4, 5]', NULL, NULL, '[{"title": "Docker 공식 문서: docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}, {"title": "Docker 공식 문서: docker compose ps", "url": "https://docs.docker.com/reference/cli/docker/compose/ps/"}, {"title": "Docker 공식 문서: docker compose logs", "url": "https://docs.docker.com/reference/cli/docker/compose/logs/"}, {"title": "Docker 공식 문서: docker compose exec", "url": "https://docs.docker.com/reference/cli/docker/compose/exec/"}, {"title": "Docker 공식 문서: Compose 파일 services", "url": "https://docs.docker.com/reference/compose-file/services/"}, {"title": "Docker 공식 문서: Compose 변수 치환", "url": "https://docs.docker.com/compose/how-tos/environment-variables/variable-interpolation/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 237 AND order_index = 12);

